ALTER TABLE users ADD COLUMN deleted_at TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS idx_users_deleted_at ON users(deleted_at);
CREATE INDEX IF NOT EXISTS idx_users_active_university ON users(university_id) WHERE deleted_at='';
CREATE TRIGGER IF NOT EXISTS users_delete_requires_team_release BEFORE UPDATE OF deleted_at ON users WHEN OLD.deleted_at='' AND NEW.deleted_at<>'' AND EXISTS(SELECT 1 FROM teams WHERE leader_user_id=OLD.id) BEGIN SELECT RAISE(ABORT,'account_deletion_requires_team_transfer'); END;
CREATE TRIGGER IF NOT EXISTS users_delete_requires_no_pending_transfer BEFORE UPDATE OF deleted_at ON users WHEN OLD.deleted_at='' AND NEW.deleted_at<>'' AND EXISTS(SELECT 1 FROM leader_transfers WHERE status='pending' AND (from_user_id=OLD.id OR to_user_id=OLD.id)) BEGIN SELECT RAISE(ABORT,'account_deletion_requires_no_pending_transfer'); END;
CREATE TRIGGER IF NOT EXISTS users_delete_requires_anonymized_fields BEFORE UPDATE OF deleted_at ON users WHEN OLD.deleted_at='' AND NEW.deleted_at<>'' AND (NEW.phone NOT LIKE 'deleted:%' OR NEW.password_hash IS NOT NULL OR NEW.name IS NOT NULL OR NEW.high_school IS NOT NULL OR NEW.class_name IS NOT NULL OR NEW.university_id IS NOT NULL OR NEW.grade IS NOT NULL OR NEW.province IS NOT NULL OR NEW.city IS NOT NULL OR NEW.bio IS NOT NULL OR NEW.phone_visible_to_team<>0 OR NEW.consent_given<>0 OR NEW.consent_at<>'' OR NEW.consent_version<>'' OR NEW.account_consent_at<>'' OR NEW.account_consent_version<>'') BEGIN SELECT RAISE(ABORT,'account_deletion_requires_full_anonymization'); END;
CREATE TRIGGER IF NOT EXISTS users_deleted_record_immutable BEFORE UPDATE ON users WHEN OLD.deleted_at<>'' BEGIN SELECT RAISE(ABORT,'deleted_account_is_immutable'); END;
CREATE TRIGGER IF NOT EXISTS teams_leader_must_be_active_insert BEFORE INSERT ON teams WHEN NEW.leader_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM users WHERE id=NEW.leader_user_id AND deleted_at<>'') BEGIN SELECT RAISE(ABORT,'team_leader_must_be_active'); END;
CREATE TRIGGER IF NOT EXISTS teams_leader_must_be_active_update BEFORE UPDATE OF leader_user_id ON teams WHEN NEW.leader_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM users WHERE id=NEW.leader_user_id AND deleted_at<>'') BEGIN SELECT RAISE(ABORT,'team_leader_must_be_active'); END;
